// Dynamic rule selection based on runtime context
public class AdvancedRuleResolver {

    public Rule resolveBusinessRule(ExecutionContext context) {
        // Multi-factor rule selection
        String region = context.getUserRegion();
        String businessUnit = context.getBusinessUnit();
        int systemLoad = context.getCurrentSystemLoad();

        // Performance-aware rule selection
        if (systemLoad > 80) {
            return getRuleVariant("optimized_performance");
        }

        // Business context rule selection
        return getRuleByCircumstance(
            region, businessUnit, context.getRegulatoryTier()
        );
    }
}
